begin;
set local row_security=on;
insert into auth.users(id) values('50193000-0000-4000-8000-000000000001'),('50193000-0000-4000-8000-000000000002');
insert into public.companies(id,name) values('50193000-0000-4000-8000-000000000010','Fictional SWMS review company');
insert into public.profiles(id,company_id,full_name,role,status) values('50193000-0000-4000-8000-000000000001','50193000-0000-4000-8000-000000000010','Fictional method author','admin','active'),('50193000-0000-4000-8000-000000000002','50193000-0000-4000-8000-000000000010','Fictional independent approver','admin','active');
create or replace function auth.uid() returns uuid language sql stable as $$select coalesce(nullif(current_setting('swms.fixture_actor',true),''),'50193000-0000-4000-8000-000000000001')::uuid$$;
grant usage on schema public,auth to authenticated;
grant select on public.profiles to authenticated;
grant select,insert,update,delete on public.documents,public.document_control_revisions,public.document_control_records,public.document_control_files,public.swms_operational_records to authenticated;
create function public.swms_fixture_fail() returns trigger language plpgsql as $$begin if current_setting('swms.fixture_fail',true)='yes' then raise exception 'Synthetic rendition failure';end if;return new;end $$;
create trigger swms_fixture_fail before insert on public.document_control_files for each row execute function public.swms_fixture_fail();
set local role authenticated;
do $$declare document_key uuid:='50193000-0000-4000-8000-000000000099';company uuid:='50193000-0000-4000-8000-000000000010';d jsonb;r public.document_control_revisions;decision jsonb;body jsonb;old_time timestamptz;next_revision text:=gen_random_uuid()::text;begin
 body:=jsonb_build_object('company_id',company,'title','Fictional SWMS only','version','2.0','doc_ref','SWMS-FICTIONAL-002','revision_summary','fictional payload');
 d:=public.save_swms_revision(document_key,null,body,'{"steps":[{"activity":"Fictional step","controls":"Fictional controls"}]}','<div class="swx-print-status">DRAFT / NOT AUTHORISED</div><p>Fictional full method</p>');
 select * into r from public.document_control_revisions where document_control_revisions.id=d->>'current_revision_id';old_time:=(d->>'updated_at')::timestamptz;
 if r.revision_code<>'2.0' or r.content_hash is null or r.content_json->>'rendition_html' not like '%Fictional full method%' or not exists(select 1 from public.document_control_files where revision_id=r.id and mime_type='text/html') then raise exception 'Atomic rendition missing';end if;
 begin perform public.save_swms_revision(document_key,null,body,'{}','x');raise exception 'Stale save accepted';exception when raise_exception then if sqlerrm not like 'SWMS changed%' then raise;end if;end;
 perform set_config('swms.fixture_fail','yes',true);
 begin perform public.save_swms_revision(document_key,old_time,jsonb_set(body,'{title}','"Lost edit"'),'{}','changed');raise exception 'Partial save accepted';exception when raise_exception then if sqlerrm<>'Synthetic rendition failure' then raise;end if;end;
 if (select title from public.documents where documents.id=document_key)<>'Fictional SWMS only' or (select content_hash from public.document_control_revisions where document_control_revisions.id=r.id)<>r.content_hash then raise exception 'Failed save lost content';end if;
 perform set_config('swms.fixture_fail','no',true);
 begin perform public.release_document_revision(document_key,r.id,r.content_hash);raise exception 'Unapproved release accepted';exception when raise_exception then if sqlerrm not like 'The current revision needs%' then raise;end if;end;
 begin perform public.decide_document_revision(document_key,r.id,r.content_hash,'approved','Self approval test');raise exception 'Self approval accepted';exception when raise_exception then if sqlerrm not like 'An independent approver%' then raise;end if;end;
 perform set_config('swms.fixture_actor','50193000-0000-4000-8000-000000000002',true);
 begin perform public.decide_document_revision(document_key,r.id,'wrong','approved','Fictional review');raise exception 'Stale decision accepted';exception when raise_exception then if sqlerrm not like 'Revision content changed%' then raise;end if;end;
 decision:=public.decide_document_revision(document_key,r.id,r.content_hash,'approved','Fictional independent review','EVIDENCE-FICTIONAL');
 if decision->'payload'->>'content_hash'<>r.content_hash or decision->>'assignee_id'<>'50193000-0000-4000-8000-000000000002' or decision->'payload'->>'revision_code'<>'2.0' then raise exception 'Decision binding missing';end if;
 if (select lifecycle_state from public.documents where documents.id=document_key)<>'approved_awaiting_release' then raise exception 'Approval state is not explicit';end if;
 begin update public.document_control_records set payload='{}' where document_control_records.id=decision->>'id';raise exception 'Decision altered';exception when raise_exception then if sqlerrm not like 'Use the authenticated%' then raise;end if;end;
 begin update public.document_control_files set file_url='https://example.invalid/altered' where revision_id=r.id;raise exception 'Approved file altered';exception when raise_exception then if sqlerrm not like 'Files bound%' then raise;end if;end;
 begin perform public.save_swms_revision(document_key,(select updated_at from public.documents where documents.id=document_key),body,'{}','changed');raise exception 'Approved content overwritten';exception when raise_exception then if sqlerrm not like 'Create a draft revision%' then raise;end if;end;
 insert into public.document_control_records(company_id,document_id,revision_id,record_type,title,status) values(company,document_key::text,r.id,'workflow_task','Fictional review task','open');
 begin perform public.release_document_revision(document_key,r.id,r.content_hash);raise exception 'Open review bypassed';exception when raise_exception then if sqlerrm not like 'Complete the outstanding%' then raise;end if;end;
 update public.document_control_records set status='completed' where document_id=document_key::text and record_type='workflow_task';
 d:=public.release_document_revision(document_key,r.id,r.content_hash);
 if d->>'lifecycle_state'<>'effective' or d->>'status'<>'current' or not exists(select 1 from public.document_control_files where revision_id=r.id and status='published') then raise exception 'Release did not reconcile state';end if;
 begin insert into public.swms_operational_records(company_id,swms_document_id,revision_code,record_type,title) values(company,document_key::text,'Rev 00','work_pack','Fictional mismatch');raise exception 'Wrong revision accepted';exception when raise_exception then if sqlerrm not like 'Select the SWMS current revision%' then raise;end if;end;
 insert into public.swms_operational_records(company_id,swms_document_id,revision_code,record_type,title) values(company,document_key::text,'2.0','work_pack','Fictional matching pack');
 -- A controller creates a revision; its actual author still cannot approve their own edits.
 insert into public.document_control_revisions(id,company_id,document_id,revision_code,status,content_json,metadata_json,source_revision_id,created_by) values(next_revision,company,document_key::text,'3.0','draft',r.content_json,r.metadata_json,r.id,auth.uid());
 update public.documents set current_revision_id=next_revision,version='3.0',approval_status='draft',lifecycle_state='under_revision',status='draft',updated_at=clock_timestamp() where documents.id=document_key;
 perform set_config('swms.fixture_actor','50193000-0000-4000-8000-000000000001',true);
 body:=jsonb_set(body,'{version}','"3.0"');
 d:=public.save_swms_revision(document_key,(select updated_at from public.documents where documents.id=document_key),body,'{"steps":[{"activity":"Revised fictional method"}]}','<p>Revised fictional rendition</p>');
 if (select status from public.document_control_revisions where id=r.id)<>'effective' or not exists(select 1 from public.document_control_files where revision_id=r.id and status='published') then raise exception 'Draft editing changed the released version';end if;
 begin perform public.decide_document_revision(document_key,next_revision,(select content_hash from public.document_control_revisions where id=next_revision),'approved','Self approval after controller revision');raise exception 'Actual author approved own revision';exception when raise_exception then if sqlerrm not like 'An independent approver%' then raise;end if;end;
 begin perform public.save_swms_revision(gen_random_uuid(),null,jsonb_set(body,'{company_id}','"50193000-0000-4000-8000-000000000020"'),'{}','foreign');raise exception 'Foreign company write accepted';exception when insufficient_privilege then null;end;
end $$;
rollback;
